# -*- coding: utf-8 -*-
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from ai_trader.journal import Journal
L = json.loads(r'''["前面几轮都在验「没跑过的路径」。这轮做一件用户明确要求、但我从没真正做过的事：","把大屏打开，亲眼看它印什么。","","=== 一、先说好的部分（这是实话）===","","因果链写得比我记忆里好。空仓状态下页头是：","","    4h K线 419 根 → SMA200 82254.3 → 现价 77866.0（-5.34%）→ 下跌趋势（价在均线下方）","    → 安全闸放行，回撤 0.0%（硬停线 60%）→ 动作：空仓等待","    → 开多触发线：涨到 82418.8（还需 +5.85%）并收盘确认","      （SMA 82254.3 × 1+0.20%，避开擦边的假突破）；","      若价格一直不动，均线自己下来也到不了这条线，所以这一笔必须靠价格自己涨","    → 历史同档等待 9.8 天（中位，P90 35.7 天，样本 333）","    → 下一根 4h 收盘 2.5 小时后 → 届时仓位：1.0x 名义 71U / qty 0.0009","","「为什么现在不交易、要涨到哪才交易、等多久算正常、下一根 K 线什么时候来、","  到时候会用多少仓位」——这一串是我要的因果，它都在。","","=== 二、第一条：先是我自己的隧道不完整（虚惊）===","","第一次打开时页头全是「--」，还写着「WS 静默」，","而 /api/health 明明 ws_connected: true、ticks_total 在涨。","控制台给了答案：WebSocket connection to 'ws://127.0.0.1:18091/ws' failed。","","大屏的实时行情走 8091（board.js 用 location.port+1 推导），我只隧道了 18090。","补上 18091 之后页头立刻有数：WS 77873.0 Δ3s 权益 71.77U tick 621。","所以这一条是我测试环境的问题，不是产品缺陷。","","=== 三、第二条：真缺陷——健康的时候喊「静默」===","","隧道补好之后，页头是这样：","","    WS  77873.0  tick 621  ...  WS 静默 1.0s","","源是 WS、tick 在涨、一切正常，却显示「WS 静默」。","「静默」两个字读起来就是「行情断了」。","","根源是 board.html 里写死的标签：<span class=\"chip\">WS 静默 <b id=\"wsIdle\"></b></span>，","而那个数只是「距上一笔多少秒」，一直在走。","","一个常驻的假告警比没有告警更糟：它会训练用户无视这一格，","真断的时候反而没人看。这和上一轮修「引擎报错没人显示」是同一个道理的两面。","","真正的告警信号早就有：快照里的 ws_silent（feed.py:344，阈值 max(60s, ws_stale_ms)），","60 秒没消息才叫静默。标签却没跟着它走。","","改法：健康说「WS 正常」，ws_silent 为真才说「WS 静默」并加警示色；秒数保留（排查要它）。","","=== 四、顺带发现：页头此前零测试覆盖 ===","","harness 里的 WebSocket 是纯空桩，而 applyState 只由 WS 推送触发——","也就是说页头这套逻辑从来没有被任何测试碰到过。","这就是为什么「健康时喊静默」能一直存在。","","扩展 harness：给它 opts.feed，在第 3 拍把 hello 快照推给页头（确定性，不用 setTimeout）。","","=== 五、变异 ===","","4 条全部变红，其中「改回固定说静默」这一条最关键——","它证明旧代码确实过不了新测试，缺陷是真的而不是我编的。","","另 3 条：永远说正常 / 静默时不给警示样式 / 不显示秒数。","","=== 六、验证 ===","","全量 457 条全绿（454 -> 457）。","","账户仍未到账（现货 USDT = 0）。"]''')
meta = json.loads(r'''{"round":91,"theme":"第一次真的打开大屏看：健康时喊「WS 静默」，且页头此前零测试覆盖","good":"因果链完整：为什么不做、涨到哪才做、等多久算正常、下一根K线何时来、届时用多少仓位，全都在","false_alarm":{"what":"页头全 -- 且显示 WS 静默，但 /api/health 正常","cause":"大屏 WS 走 8091（location.port+1），我只隧道了 18090","verdict":"我的测试环境问题，不是产品缺陷"},"real_defect":{"symptom":"src=WS、tick 在涨，页头仍显示「WS 静默 1.0s」","root":"board.html 写死标签；那个数只是距上一笔的秒数","signal_exists":"快照里的 ws_silent（feed.py:344，阈值 max(60s, ws_stale_ms)）","why_bad":"常驻的假告警会训练用户无视这一格，真断时没人看"},"coverage_gap":"harness 的 WebSocket 是纯空桩，applyState 只由 WS 触发 -> 页头逻辑此前零测试覆盖","new_tests":3,"mutation":"4/4 红，含「改回固定说静默」证明旧代码过不了","tests_total":457,"account_state":{"spot_usdt":0}}''')
J = Journal('data/market_trade.db')
J.start()
J.add('info', u'第一次真的打开大屏看：健康时喊「WS 静默」，页头此前零测试覆盖',
      chr(10).join(L), json.dumps(meta, ensure_ascii=False))
print('journal ok')
J.stop()